    progressSnapshot=d;
    if($('v309ReadinessScore'))$('v309ReadinessScore').innerHTML=scoreCard('AI Readiness Score',d.readiness,'Preparation intelligence, not result prediction','readiness');if($('v309PrelimsScore'))$('v309PrelimsScore').innerHTML=scoreCard('Prelims',d.prelims,`Accuracy ${d.preAccuracy??'—'} • revision + CA`,'prelims');if($('v309MainsScore'))$('v309MainsScore').innerHTML=scoreCard('Mains',d.mains,`${d.mainsCount} answers • avg ${d.mainsAvg??'—'}`,'mains');if($('v309DisciplineScore'))$('v309DisciplineScore').innerHTML=scoreCard('Discipline',d.discipline,`${d.activeDays}/${d.days} active days • ${d.streak} streak`,'discipline');
